insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('964cb6eb-3613-4db5-b3c0-c1ea47be410a', 6, 'pergunta_checkpoint', '{"codigo":"triagem_menu","mensagens":[{"tipo":"texto","texto":"Para agilizar seu atendimento, informe o número da opção:\n\n1️⃣ Limpeza de Nome (CPF/CNPJ)\n2️⃣ Aumento de Score / Rating\n3️⃣ BACEN / SCR / CCF\n4️⃣ Jusbrasil / Escavador\n5️⃣ Conta Protegida (Bloqueio Judicial)\n6️⃣ Consórcio\n7️⃣ Crédito / Financiamento\n8️⃣ Outro assunto\n\n👉 *É só responder com o número da opção* 😊"}],"aguarda_resposta":true,"tipo_resposta":"menu","opcoes":[{"valor":"limpeza_nome","rotulos":["1","1️⃣"],"proximo_codigo":"ln_passo2"},{"valor":"score","rotulos":["2","2️⃣"],"proximo_codigo":"handoff_humano"},{"valor":"bacen_scr_ccf","rotulos":["3","3️⃣"],"proximo_codigo":"handoff_humano"},{"valor":"jusbrasil_escavador","rotulos":["4","4️⃣"],"proximo_codigo":"handoff_humano"},{"valor":"conta_protegida","rotulos":["5","5️⃣"],"proximo_codigo":"handoff_humano"},{"valor":"consorcio","rotulos":["6","6️⃣"],"proximo_codigo":"handoff_humano"},{"valor":"credito","rotulos":["7","7️⃣"],"proximo_codigo":"handoff_humano"},{"valor":"outro_assunto","rotulos":["8","8️⃣"],"proximo_codigo":"handoff_humano"}],"kanban_subetapa":"novo_lead_triagem"}'::jsonb, 'produto_interesse');
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('964cb6eb-3613-4db5-b3c0-c1ea47be410a', 7, 'mensagem_sequencial', '{"codigo":"handoff_humano","mensagens":[{"tipo":"texto","texto":"Perfeito! Esse assunto eu já vou encaminhar direto para um de nossos consultores te ajudar — só um instante 🙋‍♂️"}],"aguarda_resposta":false,"encerramento":{"sob_supervisor":true},"kanban_subetapa":"novo_lead_triagem"}'::jsonb, null);
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 2, 'pergunta_checkpoint', '{"codigo":"ln_passo2","mensagens":[{"tipo":"texto","texto":"🤔 Se você responder 4 perguntas rápidas, em menos de um minuto eu já consigo informar o valor exato para limpar o seu nome. Depois disso, tiro todas as suas dúvidas e, se preferir, também podemos conversar por ligação.\n\n👉 *Podemos começar?*"}],"aguarda_resposta":true,"tipo_resposta":"sim_nao","opcoes":[{"valor":"sim","rotulos":["sim","s"],"proximo_codigo":"ln_passo3"},{"valor":"nao","rotulos":["nao","n"],"proximo_codigo":"ln_aguardar_melhor_momento"}],"kanban_subetapa":"qualificacao"}'::jsonb, null);
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 3, 'mensagem_sequencial', '{"codigo":"ln_aguardar_melhor_momento","mensagens":[{"tipo":"texto","texto":"Sem problema! Fico por aqui e retomo com você mais tarde, combinado? 🙂"}],"aguarda_resposta":false,"encerramento":{"sob_supervisor":false},"kanban_subetapa":"qualificacao"}'::jsonb, null);
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 4, 'mensagem_sequencial', '{"codigo":"ln_passo3","mensagens":[{"tipo":"texto","texto":"✅ A proposta do nosso trabalho é remover as restrições que estão negativando seu CPF ou CNPJ — independentemente da origem: contas não pagas, cartão de crédito, empréstimos, financiamentos, protestos, cheques devolvidos ou ações de cobrança.\n\n👉 O objetivo é que seu nome fique limpo, permitindo que você recupere sua reputação financeira e consiga voltar a pleitear acesso a crédito no mercado."},{"tipo":"texto","texto":"⚖️ O procedimento é realizado por meio de ação judicial coletiva via associação de proteção ao consumidor, garantindo direitos previstos em lei, removendo as restrições no SERASA, SPC Brasil, SCPC Boa Vista e CENPROT (Central Nacional de Protestos).\n\n📌 O serviço conta com seguro-garantia de manutenção do nome limpo pelo período de 1 ANO, conforme condições contratuais (após 12 meses as restrições podem retornar se não forem negociadas ou pagas neste período)."},{"tipo":"texto","texto":"⚠️ Importante entender: RESTRIÇÃO é uma coisa, DÍVIDA é outra! As restrições que hoje estão negativando seu nome nestes orgãos serão 100% removidas. Já as dívidas, continuarão existindo de forma interna no credor e nos sistemas do Banco Central.\n\n✅ Em resumo: uma forma rápida e legal de obter CPF ou CNPJ limpo no sistema Serasa/SPC por um custo menor do que se fosse pagar as dívidas."}],"aguarda_resposta":false,"proximo_codigo":"ln_passo4","kanban_subetapa":"qualificacao"}'::jsonb, null);
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 5, 'pergunta_checkpoint', '{"codigo":"ln_passo4","mensagens":[{"tipo":"texto","texto":"👉 Você precisa limpar o *CPF* ou *CNPJ*?"}],"aguarda_resposta":true,"tipo_resposta":"menu","opcoes":[{"valor":"cpf","rotulos":["cpf"],"proximo_codigo":"ln_passo5"},{"valor":"cnpj","rotulos":["cnpj"],"proximo_codigo":"ln_passo5"},{"valor":"cpf_e_cnpj","rotulos":["cpf e cnpj","os dois","ambos","cnpj e cpf"],"proximo_codigo":"ln_passo5"}],"kanban_subetapa":"qualificacao"}'::jsonb, 'tipo_documento');
