insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 7, 'pergunta_checkpoint', '{"codigo":"ln_passo6","mensagens":[{"tipo":"texto","texto":"👉 *Em qual das faixas abaixo melhor se enquadra o valor das restrições neste CPF atualmente?* (tudo bem se não tiver certeza - depois faremos uma consulta)\n\n1️⃣ Menos de 10 mil\n2️⃣ Entre 10 e 30 mil\n3️⃣ Entre 30 e 50 mil\n4️⃣ Entre 50 e 100 mil\n5️⃣ Mais de 100 mil"}],"aguarda_resposta":true,"tipo_resposta":"menu","opcoes":[{"valor":"menos_10mil","rotulos":["1","1️⃣"],"proximo_codigo":"ln_passo6_refino_baixo"},{"valor":"10_30mil","rotulos":["2","2️⃣"],"proximo_codigo":"ln_passo8"},{"valor":"30_50mil","rotulos":["3","3️⃣"],"proximo_codigo":"ln_passo8"},{"valor":"50_100mil","rotulos":["4","4️⃣"],"proximo_codigo":"ln_passo8"},{"valor":"mais_100mil","rotulos":["5","5️⃣"],"proximo_codigo":"ln_passo6_refino_alto"}],"kanban_subetapa":"faixa_divida"}'::jsonb, 'faixa_valor');
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 8, 'pergunta_checkpoint', '{"codigo":"ln_passo6_refino_baixo","mensagens":[{"tipo":"texto","texto":"Entendo, para eu conseguir te orientar melhor me responda:\n\n1️⃣ Menos de 3 Mil\n2️⃣ Entre 3 e 10 Mil"}],"aguarda_resposta":true,"tipo_resposta":"menu","opcoes":[{"valor":"menos_3mil","rotulos":["1","1️⃣"],"proximo_codigo":"ln_passo7"},{"valor":"3_10mil","rotulos":["2","2️⃣"],"proximo_codigo":"ln_passo8"}],"kanban_subetapa":"faixa_divida"}'::jsonb, 'faixa_valor_detalhe');
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 9, 'pergunta_checkpoint', '{"codigo":"ln_passo6_refino_alto","mensagens":[{"tipo":"texto","texto":"Entendi que são mais de 100 mil reais, para eu conseguir te orientar melhor, preciso que me informe o valor aproximado das restrições - pode escrever... (tudo bem se não tiver certeza - depois faremos uma consulta)"}],"aguarda_resposta":true,"tipo_resposta":"numero_ou_nao_sei","proximo_codigo":"ln_passo8","kanban_subetapa":"faixa_divida","interpretacao_ia":{"habilitado":true,"instrucao":"O lead pode responder o valor aproximado da restrição de forma bem livre (por extenso, com gírias, faixa vaga tipo ''uns 200 e pouco''). Extraia um número em reais o mais próximo possível do que ele quis dizer."}}'::jsonb, 'valor_aproximado');
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 10, 'pergunta_checkpoint', '{"codigo":"ln_passo7","mensagens":[{"tipo":"texto","texto":"😊 Aqui na ArrudaCred nós sempre buscamos orientar o cliente da forma que entendemos ser mais vantajosa para ele.\n\nComo o valor total das restrições é inferior a R$ 3.000, vale a pena considerar que nosso serviço de limpeza de nome tem um investimento mínimo de R$ 899 à vista ou 6x de R$ 299. Além disso, é importante lembrar que as dívidas continuam existindo, ou seja, a ação remove as restrições, mas não quita os débitos.\n\nPor isso, nesse cenário, nossa recomendação é que você avalie a possibilidade de negociar e quitar diretamente essas dívidas, pois, financeiramente, essa costuma ser a opção mais vantajosa.\n\nSe, ainda assim, você preferir seguir com a ação para remover as restrições do seu nome, será um prazer ajudar. Podemos continuar?"}],"aguarda_resposta":true,"tipo_resposta":"sim_nao","opcoes":[{"valor":"sim","rotulos":["sim","s"],"proximo_codigo":"ln_passo8"},{"valor":"nao","rotulos":["nao","n"],"encerra_com_perda":true,"motivo_perda":"LEAD OPTOU POR NEGOCIAR DÍVIDA DIRETAMENTE"}],"kanban_subetapa":"faixa_divida"}'::jsonb, null);
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 11, 'condicional', '{"codigo":"ln_passo8","mensagens":[{"tipo":"texto","texto":"👍 Entendido! Me conta: você já contratou algum serviço de limpeza de nome antes? E como conheceu a ArrudaCred? Foi indicação de alguém? 🤔"}],"aguarda_resposta":true,"tipo_resposta":"texto_livre","proximo_condicional":{"contem_qualquer":["google","internet","site","instagram","facebook","busca","pesquis"],"se_sim":"ln_passo9","se_nao":"ln_passo10"},"kanban_subetapa":"faixa_divida"}'::jsonb, 'experiencia_e_origem');
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 12, 'mensagem_sequencial', '{"codigo":"ln_passo9","mensagens":[{"tipo":"texto","texto":"Obrigado por nos informar, estamos bem posicionados nos mecanismos de busca justamente por conta da nossa reputação e boa avaliação de clientes que já nos contrataram..."}],"aguarda_resposta":false,"proximo_codigo":"ln_passo10","kanban_subetapa":"faixa_divida"}'::jsonb, null);
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 13, 'mensagem_sequencial', '{"codigo":"ln_passo10","mensagens":[{"tipo":"texto","texto":"Pergunto porque para nós a relação com nossos clientes vale mais que uma venda isolada, assim ganhamos indicações com a confiança estabelecida. Entendemos a preocupação de quem ainda não nos conhece e tem medo de cair num golpe ou na mão de gente desonesta..."}],"aguarda_resposta":false,"proximo_codigo":"ln_passo11","kanban_subetapa":"faixa_divida"}'::jsonb, null);
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 14, 'mensagem_sequencial', '{"codigo":"ln_passo11","mensagens":[{"tipo":"texto","texto":"⭐⭐⭐⭐⭐\nSomos uma empresa com 5 anos de atuação no mercado de recuperação de crédito, trabalhando sempre com contrato para prestação de serviços, que deixa claro os direitos e deveres tanto do cliente quanto da empresa.\n\n👉 *Não existe milagre. O que existe é processo dentro da lei, contrato, prazo e compromisso.*\n👉 No último ano, auxiliamos mais de 5 mil clientes em processos de regularização de crédito.\n👉 Atualmente temos avaliação 4,9 no Google (o máximo é nota 5,0) e avaliação 9,5 no Reclame Aqui (máximo é nota 10)."},{"tipo":"texto","texto":"📌 Dados da empresa:\nARRUDACRED – HUB ARRUDA DE NEGÓCIOS E SERVIÇOS\nL.H. DE ARRUDA D. DO VALLE SERVIÇOS LTDA\nCNPJ: 40.342.851/0001-37\n\n🌐 Site: https://www.arrudacred.com.br\n\n📷 Instagram:\nhttps://instagram.com/arrudacred.br\n\n*Trabalhamos com foco em transparência e segurança para o cliente, oferecendo*:\n\n✅ Contrato de prestação de serviços\n✅ Google com avaliação 5 estrelas\n✅ Reclame Aqui com avaliação 9,5 (ótima)\n✅ Mais de 5 mil clientes atendidos\n✅ Seguro Garantia de 12 meses incluso"},{"tipo":"imagem","midia_url":"","legenda":"Selo do Prêmio Reclame Aqui 2026 (círculo verde escuro, \"Melhores empresas para o consumidor 2026\")"},{"tipo":"texto","texto":"A *ARRUDACRED* está concorrendo ao *Prêmio Reclame AQUI*. Nossa empresa foi indicada na categoria RECUPERAÇÃO DE CRÉDITO, junto de outras grandes no segmento, como CENPROT NACIONAL E SPC BRASIL.\n\nVeja você mesmo:\n📌 https://www.reclameaqui.com.br/premio/classificadas-indicadas/financeiras/"}],"aguarda_resposta":false,"proximo_codigo":"ln_passo12","kanban_subetapa":"faixa_divida"}'::jsonb, null);
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 15, 'pergunta_checkpoint', '{"codigo":"ln_passo12","mensagens":[{"tipo":"texto","texto":"📣 *Para eu conseguir te orientar melhor me diz: para quando você tem necessidade do CPF limpo?*\n\n1️⃣ Só está pesquisando\n2️⃣ Urgente\n3️⃣ Em 30-45 dias\n4️⃣ 3 a 6 meses\n5️⃣ Outro, me explique!"}],"aguarda_resposta":true,"tipo_resposta":"menu","opcoes":[{"valor":"pesquisando","rotulos":["1","1️⃣"],"proximo_codigo":"ln_passo13"},{"valor":"urgente","rotulos":["2","2️⃣"],"proximo_codigo":"ln_passo13"},{"valor":"30_45_dias","rotulos":["3","3️⃣"],"proximo_codigo":"ln_passo13"},{"valor":"3_6_meses","rotulos":["4","4️⃣"],"proximo_codigo":"ln_passo13"},{"valor":"outro","rotulos":["5","5️⃣"],"proximo_codigo":"ln_passo12_explique"}],"kanban_subetapa":"faixa_divida"}'::jsonb, 'urgencia');
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 16, 'pergunta_checkpoint', '{"codigo":"ln_passo12_explique","mensagens":[{"tipo":"texto","texto":"Pode me explicar melhor a sua situação de prazo?"}],"aguarda_resposta":true,"tipo_resposta":"texto_livre","proximo_codigo":"ln_passo13","kanban_subetapa":"faixa_divida"}'::jsonb, 'urgencia_detalhe');
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 17, 'mensagem_sequencial', '{"codigo":"ln_passo13","mensagens":[{"tipo":"texto","texto":"Vejo que não tem tempo sobrando, o prazo normal para o resultado é de 7 a 45 dias úteis mas depende de um processo judicial, portanto pode variar. Entender que, quanto antes der entrada mais rápido sai o resultado, pode ajudar na sua situação..."}],"aguarda_resposta":false,"proximo_codigo":"ln_passo14","kanban_subetapa":"faixa_divida"}'::jsonb, null);
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 18, 'pergunta_checkpoint', '{"codigo":"ln_passo14","mensagens":[{"tipo":"texto","texto":"📌 Nós recebemos alguns vouchers da Associação que nos permitem oferecer uma condição especial muito expressiva. Como são limitados, para liberar a proposta com a melhor condição possível, precisamos saber:\n\n👉 *É prioridade para você já entrar com o CPF para ser limpo e começar a contar o prazo hoje?*\n1️⃣ Sim\n2️⃣ Não"}],"aguarda_resposta":true,"tipo_resposta":"menu","opcoes":[{"valor":"sim","rotulos":["1","1️⃣","sim"],"proximo_codigo":"ln_passo15_router"},{"valor":"nao","rotulos":["2","2️⃣","nao"],"proximo_codigo":"ln_passo15_router"}],"kanban_subetapa":"faixa_divida"}'::jsonb, 'prioridade_fechar_hoje');
