insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 27, 'pergunta_checkpoint', '{"codigo":"ln_passo18","mensagens":[{"tipo":"texto","texto":"Estamos quase concluindo! Agora falta somente a foto ou PDF de um documento válido (RG ou CNH) + comprovante de residência da pessoa que vai assinar o contrato. (se não tiver em mãos para enviar neste momento, me avise que anotamos aqui para você enviar depois.)"}],"aguarda_resposta":true,"tipo_resposta":"texto_livre","proximo_codigo":"ln_encerramento","kanban_subetapa":"dados_contrato"}'::jsonb, 'documentos_status');
insert into etapas_fluxo (fluxo_id, ordem, tipo_etapa, conteudo, campo_salvo) values ('7e410b97-3cc1-4118-bdfe-5ac9e3dedf62', 28, 'mensagem_sequencial', '{"codigo":"ln_encerramento","mensagens":[{"tipo":"texto","texto":"😊 Perfeito! Já anotei tudo aqui. Nossa equipe vai preparar seu contrato e te aviso por aqui assim que estiver tudo pronto pra você assinar. Muito obrigada pela confiança! 🙌"}],"aguarda_resposta":false,"encerramento":{"sob_supervisor":true},"kanban_subetapa":"dados_contrato"}'::jsonb, null);
insert into faqs (produto_id, pergunta, resposta) values ('aaf16cb9-ba7a-43c6-b1a6-ce4d4202824f', 'É certeza que vou conseguir aprovação de crédito após limpar meu nome?', 'A maioria dos clientes consegue aprovação de crédito/financiamento algumas semanas após a conclusão do processo, mas lojas e principalmente instituições financeiras usam outros critérios além do nome limpo para aprovar crédito — nome limpo não é garantia de aprovação.
insert into faqs (produto_id, pergunta, resposta) values ('aaf16cb9-ba7a-43c6-b1a6-ce4d4202824f', 'O score vai aumentar depois de limpar o nome?', 'Score é o resultado de um cálculo matemático sobre a situação financeira: restrição = score baixo; nome limpo = tendência de melhora. Sim, o score vai melhorar conforme as dívidas são pagas ou as restrições removidas — de forma gradativa. Exceção: se o cliente tiver contas do mês atual atrasadas/vencidas, o score pode ficar travado ou até cair.');
insert into faqs (produto_id, pergunta, resposta) values ('aaf16cb9-ba7a-43c6-b1a6-ce4d4202824f', 'Quando e quanto o score aumenta?', 'Não é possível precisar quanto nem quando — depende do algoritmo do Serasa (hoje usa IA e muda constantemente). Regra geral: se o CPF não tiver contas atrasadas nos últimos 30 dias, já sobe um pouco de cara. O aumento mais relevante é gradativo ao longo dos próximos 90 dias, desde que o cliente mantenha hábitos de bom pagador e poucas consultas no nome.');
insert into faqs (produto_id, pergunta, resposta) values ('aaf16cb9-ba7a-43c6-b1a6-ce4d4202824f', 'As restrições podem voltar? O que é o seguro-garantia?', 'O processo é judicial, então é normal os órgãos de proteção ao crédito apresentarem recursos ao longo do tempo — isso pode fazer restrições voltarem (parcial ou totalmente). Não é falha no serviço, é andamento normal do processo.
insert into faqs (produto_id, pergunta, resposta) values ('aaf16cb9-ba7a-43c6-b1a6-ce4d4202824f', 'Qual a diferença entre restrição e dívida?', 'Restrição = anotação negativa referente à dívida que prejudica o nome — a ArrudaCred consegue baixar isso via ação judicial com base no Decreto nº 2.181/97 (art. 13, incisos XIII e XIV), no art. 42 do Código de Defesa do Consumidor e na Súmula 359 do STJ.
insert into faqs (produto_id, pergunta, resposta) values ('aaf16cb9-ba7a-43c6-b1a6-ce4d4202824f', 'Posso resolver o BACEN/SCR/CCF junto com a Limpeza de Nome Serasa/SPC?', '*Bacen depois da proposta Limpa Nome SERASA/SPC!!*
insert into faqs (produto_id, pergunta, resposta) values ('aaf16cb9-ba7a-43c6-b1a6-ce4d4202824f', 'Quais as garantias que eu tenho contratando a ArrudaCred?', 'Essa é uma ótima pergunta, e eu também faria essa pergunta no seu lugar. 😊
insert into faqs (produto_id, pergunta, resposta) values ('aaf16cb9-ba7a-43c6-b1a6-ce4d4202824f', 'Posso ver uma minuta do contrato?', 'Claro! 😊 Antes da assinatura você receberá o contrato completo para analisar com calma. Como ele é elaborado com os dados do cliente e do serviço contratado, não trabalhamos com uma minuta padrão. Se surgir qualquer dúvida, faço questão de explicar cada cláusula antes da assinatura.');
insert into faqs (produto_id, pergunta, resposta) values ('aaf16cb9-ba7a-43c6-b1a6-ce4d4202824f', 'Como funciona o processo de limpeza de nome?', 'A limpeza de nome é realizada por meio de uma ação judicial coletiva, promovida por associações de defesa dos direitos do consumidor, com fundamento no Decreto nº 2.181/97 (art. 13, incisos XIII e XIV), no art. 42 do Código de Defesa do Consumidor e na Súmula 359 do Superior Tribunal de Justiça (STJ). O objetivo da ação é buscar a remoção das restrições dos órgãos de proteção ao crédito, sem quitar ou extinguir as dívidas, que continuam existindo normalmente.
insert into faqs (produto_id, pergunta, resposta) values ('aaf16cb9-ba7a-43c6-b1a6-ce4d4202824f', 'Existe chance das restrições voltarem?', 'Sim, essa possibilidade existe. 😊
